/**
 * Lightweight CPU benchmark for the preprocessing pipeline — Phase 2
 */

import { FrameCapture } from './FrameCapture';
import { ProcessingPipeline } from './Pipeline';
import type { PipelineMetrics } from './types';

export interface BenchmarkResult {
  runs: number;
  avgCaptureMs: number;
  avgProcessMs: number;
  avgTotalMs: number;
  minTotalMs: number;
  maxTotalMs: number;
  lastMetrics: PipelineMetrics | null;
  offscreen: boolean;
}

/**
 * Run N capture+process cycles against a live video element.
 * Caller must ensure the video is playing with a valid stream.
 */
export async function runPipelineBenchmark(
  video: HTMLVideoElement,
  pipeline: ProcessingPipeline,
  runs = 30,
  maxWidth = 640
): Promise<BenchmarkResult> {
  const capture = new FrameCapture();
  const totals: number[] = [];
  const captures: number[] = [];
  const processes: number[] = [];
  let last: PipelineMetrics | null = null;

  // Warm-up
  for (let i = 0; i < 3; i++) {
    const t0 = performance.now();
    const frame = capture.captureFromVideo(video, { maxWidth });
    const capMs = performance.now() - t0;
    const { metrics } = pipeline.run(frame);
    metrics.captureMs = capMs;
    metrics.totalMs = capMs + metrics.processMs;
  }

  for (let i = 0; i < runs; i++) {
    const t0 = performance.now();
    const frame = capture.captureFromVideo(video, { maxWidth });
    const capMs = performance.now() - t0;
    const { metrics } = pipeline.run(frame);
    metrics.captureMs = capMs;
    metrics.totalMs = capMs + metrics.processMs;
    last = metrics;
    captures.push(capMs);
    processes.push(metrics.processMs);
    totals.push(metrics.totalMs);
    // Yield so UI stays responsive
    if (i % 5 === 4) {
      await new Promise((r) => setTimeout(r, 0));
    }
  }

  const avg = (arr: number[]) => arr.reduce((a, b) => a + b, 0) / arr.length;

  return {
    runs,
    avgCaptureMs: avg(captures),
    avgProcessMs: avg(processes),
    avgTotalMs: avg(totals),
    minTotalMs: Math.min(...totals),
    maxTotalMs: Math.max(...totals),
    lastMetrics: last,
    offscreen: capture.supportsOffscreen,
  };
}
